(() => {
  const {$,esc,normalize,read,write,toast}=Atlas;const lessons=window.ATLAS_LESSONS;const quiz=window.ATLAS_QUIZ;
  const sources={play:['Guia oficial de jogo','https://en.onepiece-cardgame.com/play-guide/'],manual:['Manual oficial, v1.11','https://en.onepiece-cardgame.com/pdf/rule_manual.pdf'],comprehensive:['Regras completas, v1.2.1 (28/08/2026)','https://en.onepiece-cardgame.com/pdf/rule_comprehensive.pdf'],overview:['Resumo oficial em português','https://en.onepiece-cardgame.com/pdf/rule_overview_sheet_pt.pdf'],faq:['FAQ de regras gerais','https://en.onepiece-cardgame.com/pdf/qa_rules.pdf'],cardlist:['Catálogo oficial Bandai','https://en.onepiece-cardgame.com/cardlist/'],block:['Sistema de blocos e formatos','https://en.onepiece-cardgame.com/topics/013.php'],rules:['Regras, atualizações e erratas','https://en.onepiece-cardgame.com/rules/']};
  const stored=read('atlas-lessons',[]);let completed=Array.isArray(stored)?stored.filter(id=>lessons.some(l=>l.id===id)):[];let current=0;
  function updateProgress(){const percent=Math.round(completed.length/lessons.length*100);$('#course-percent').textContent=percent+'%';$('#course-bar').style.width=percent+'%';$('#course-progress-label').textContent=completed.length+' de '+lessons.length+' capítulos concluídos';$('#lesson-nav').innerHTML=lessons.map((l,i)=>`<a href="#${l.id}" class="${i===current?'selected ':''}${completed.includes(l.id)?'completed':''}" ${i===current?'aria-current="location"':''}><span>${completed.includes(l.id)?'✓':String(i+1).padStart(2,'0')}</span>${l.title}${i===current?'<i>→</i>':''}</a>`).join('');}
  const scrollLesson=()=>$('#lesson-article').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});
  function render(scroll=false){const id=decodeURIComponent(location.hash.slice(1));current=Math.max(0,lessons.findIndex(l=>l.id===id));const lesson=lessons[current];$('#lesson-article').innerHTML=`<div class="lesson-header"><span>CAPÍTULO ${String(current+1).padStart(2,'0')} / ${lessons.length}</span><h2>${lesson.title}</h2><p>${lesson.subtitle}</p><small class="reading-time">◷ Aproximadamente ${lesson.time} · Revisão de fontes: 23/10/2026</small></div><div class="lesson-body">${lesson.html}<p class="lesson-source">Fontes para conferir as regras: ${lesson.sources.map(k=>`<a href="${sources[k][1]}" target="_blank" rel="noopener">${sources[k][0]} ↗</a>`).join(' · ')}. Exemplos e exercícios são didáticos; o texto vigente da carta e as atualizações oficiais devem ser consultados em interações específicas.</p></div><label class="lesson-complete"><input type="checkbox" id="lesson-complete" ${completed.includes(lesson.id)?'checked':''}> Marcar este capítulo como concluído</label><div class="lesson-controls">${current>0?`<a class="btn-outline" href="#${lessons[current-1].id}">← Capítulo anterior</a>`:'<a class="btn-outline" href="home.html">← Explorar cartas</a>'}${current<lessons.length-1?`<a class="btn-gold" href="#${lessons[current+1].id}">Próximo capítulo →</a>`:'<a class="btn-gold" href="home.html">Explorar a biblioteca ↗</a>'}</div>`;$('#lesson-complete').onchange=e=>{completed=e.target.checked?[...new Set([...completed,lesson.id])]:completed.filter(x=>x!==lesson.id);if(!write('atlas-lessons',completed))toast('O progresso não pôde ser salvo neste navegador.');updateProgress();};updateProgress();initLesson(lesson.id);document.title=lesson.title+' — Academia Pirata · Grand Line Atlas';if(scroll){scrollLesson();$('#lesson-article').focus({preventScroll:true});}}
  window.addEventListener('hashchange',()=>render(true));
  $('#resume-course').onclick=()=>{const lesson=lessons.find(l=>!completed.includes(l.id))||lessons.at(-1);if(location.hash==='#'+lesson.id)scrollLesson();else location.hash=lesson.id;};
  $('#reset-course').onclick=()=>{completed=[];write('atlas-lessons',completed);render();toast('Progresso de leitura reiniciado.');};
  $('#lesson-search').oninput=e=>{const q=normalize(e.target.value.trim());const result=$('#lesson-search-results');result.hidden=!q;if(!q){result.innerHTML='';return;}const matches=lessons.filter(l=>normalize(l.title+' '+l.subtitle+' '+l.html.replace(/<[^>]+>/g,' ')).includes(q));result.innerHTML=matches.length?matches.map(l=>`<a href="#${l.id}">${l.title} ↗</a>`).join(''):'<p>Nenhum capítulo encontrado. Tente “DON”, “vida” ou “Counter”.</p>';};
  function setupTabs(buttons,select){const list=[...buttons];list.forEach((b,i)=>{b.onclick=()=>select(b);b.onkeydown=e=>{let next=i;if(e.key==='ArrowRight')next=(i+1)%list.length;else if(e.key==='ArrowLeft')next=(i+list.length-1)%list.length;else if(e.key==='Home')next=0;else if(e.key==='End')next=list.length-1;else return;e.preventDefault();select(list[next]);list[next].focus();};});}
  function initLesson(id){
    if(id==='tipos'){
      const info={leader:['Líder','assets/OP01-003.png','Fica na área de Líder desde o início e pode atacar e usar habilidades. Sua vida impressa determina a quantidade inicial de cartas de vida. Suas cores orientam o deck principal.'],character:['Personagem','assets/OP01-025.png','É jogado na área de Personagens, normalmente pagando seu custo. Tem poder, atributo e possíveis efeitos ou Counter. Você pode manter até cinco Personagens no campo. Normalmente não ataca no turno em que entra.'],event:['Evento','assets/OP01-029.png','Resolve seu efeito e vai ao descarte, seguindo a janela indicada. Main é usado na fase principal; Counter, na etapa de Counter. Custos e condições continuam valendo, salvo exceção expressa.'],stage:['Cenário','assets/EB01-011.png','Fica na área de Cenário e oferece os efeitos descritos na carta. O limite normal é um por jogador. Jogar outro permite substituir o anterior, que vai ao descarte pelo procedimento adequado.'],don:['DON!!',null,'Recurso separado do deck principal. Na área de custo, pode pagar jogadas; atribuído ao Líder ou Personagem, fornece o aumento normal de poder no seu turno. Existe um deck próprio de dez DON!!.']};
      const buttons=document.querySelectorAll('[data-teach-type]');const select=b=>{buttons.forEach(t=>{t.setAttribute('aria-selected',String(t===b));t.tabIndex=t===b?0:-1;});const v=info[b.dataset.teachType];$('#teaching-type').setAttribute('aria-labelledby',b.id);$('#teaching-type').innerHTML=(v[1]?`<img src="${v[1]}" alt="Exemplo de ${v[0]}">`:'<div class="don-demo" role="img" aria-label="Representação didática de uma carta DON!!"><b>DON!!</b><small>SEU TURNO +1000</small></div>')+`<div><h3>${v[0]}</h3><p>${v[2]}</p></div>`;};setupTabs(buttons,select);select(buttons[0]);
    }
    if(id==='anatomia'){
      const parts={cost:['1. Custo','O número no canto superior esquerdo de um Personagem indica quanto DON!! você normalmente precisa descansar para jogá-lo. Aqui, o custo é três. Líderes exibem vida, não custo de jogar.'],power:['2. Poder e atributo','Esta versão de Zoro possui 5000 de poder e atributo Slash. O poder entra na comparação de combate. Slash pode ser referenciado por efeitos, mas não cria vantagem automática sobre outro atributo.'],counter:['3. Counter','Se um Personagem tiver Counter impresso, você pode usá-lo da mão na etapa de Counter. OP01-025 não possui Counter impresso; não presuma que toda carta de Personagem oferece +1000.'],effect:['4. Efeito','OP01-025 possui Rush: permite atacar no turno em que é jogado, respeitando as proibições gerais. O texto oficial e possíveis erratas determinam o comportamento.'],identity:['5. Nome, características e ID','O ID OP01-025 identifica a carta de regra. Abaixo do nome ficam características como Supernovas e Straw Hat Crew. A raridade e a impressão ajudam a distinguir versões; bloco e Blocker são campos diferentes.']};const select=key=>$('#anatomy-description').innerHTML=`<h3>${parts[key][0]}</h3><p>${parts[key][1]}</p>`;document.querySelectorAll('[data-part]').forEach(b=>b.onclick=()=>select(b.dataset.part));select('cost');
    }
    if(id==='campo'){
      const zones={characters:['Personagens','Até cinco cartas. Personagens descansados podem ser alvos normais de ataque adversário; ativos normalmente não podem ser escolhidos como alvo de ataque, salvo efeitos.'],leader:['Líder','Sua carta central, revelada desde o início. Mesmo ativa, pode ser escolhida como alvo de ataque. Dano ao Líder interage com a área de vida.'],stage:['Cenário','Uma carta de Cenário por jogador no limite normal. Não é um Personagem e não participa de combate apenas por estar no campo.'],deck:['Deck principal','As cinquenta cartas são embaralhadas no início. Vida e mão inicial saem daqui. Ficar com zero cartas nesse deck é uma condição de derrota.'],trash:['Descarte / Trash','Recebe cartas conforme as regras e efeitos: Personagens que sofrem K.O., Eventos usados, descartes de mão e outras instruções. Descarte não é o deck de DON!!.'],cost:['Área de custo','DON!! ativos aqui pagam custos e podem ser atribuídos. DON!! descansados não pagam novamente um custo que exige descansá-los.'],don:['Deck de DON!!','Começa com dez recursos. A DON!! Phase move os recursos disponíveis para a área de custo. Ficar sem cartas no deck de DON!! não é a condição de derrota por deck vazio.'],life:['Vida','Quantidade inicial definida pelo Líder. Normalmente é uma área oculta. Ao receber dano, a carta de cima vai à mão ou participa do procedimento de Trigger, quando aplicável.']};const select=key=>{document.querySelectorAll('[data-zone]').forEach(b=>b.classList.toggle('selected',b.dataset.zone===key));$('#zone-description').innerHTML=`<b>${zones[key][0]}</b><p>${zones[key][1]}</p>`;};document.querySelectorAll('[data-zone]').forEach(b=>b.onclick=()=>select(b.dataset.zone));select('characters');
    }
    if(id==='turno'){
      let phase=0;const renderPhase=()=>{const first=$('#first-player').checked&&$('#first-turn').checked;const firstTurn=$('#first-turn').checked;const text=[['Refresh · Reorganize seus recursos','Resolva os procedimentos de início de turno, retorne DON!! atribuídos à área de custo e reative as cartas conforme as regras. As durações de efeitos podem exigir processamento antes da reativação.'],['Draw · Compre uma carta',first?'Você começou a partida e está no primeiro turno: não compra carta nesta fase. Nos turnos seguintes, compra normalmente uma carta.':'Compre uma carta do deck principal. Se você é o segundo jogador, compra também no seu primeiro turno.'],['DON!! · Receba recursos',first?'Coloque um DON!! do deck de DON!! na área de custo, ativo. É a exceção do primeiro jogador no primeiro turno.':'Coloque dois DON!! do deck de DON!! na área de custo, ativos. Se só restar um, coloque um; se não houver, não adicione.'],['Main · Faça suas jogadas',firstTurn?'Jogue cartas, use habilidades e distribua DON!! conforme permitido. Este é seu primeiro turno: você não pode atacar, mesmo que seja o segundo jogador ou tenha Rush.':'Jogue cartas, use habilidades, distribua DON!! e faça ataques legais em qualquer ordem. Lembre-se: Personagens recém-jogados normalmente não podem atacar.'],['End · Encerre o turno','Resolva os efeitos de fim de turno e encerre as durações aplicáveis na ordem das regras. Só depois passe a vez ao oponente.']];document.querySelectorAll('[data-phase]').forEach(b=>b.classList.toggle('selected',+b.dataset.phase===phase));$('#turn-description').innerHTML=`<h3>${text[phase][0]}</h3><p>${text[phase][1]}</p>`;};document.querySelectorAll('[data-phase]').forEach(b=>b.onclick=()=>{phase=+b.dataset.phase;renderPhase();});$('#first-player').onchange=renderPhase;$('#first-turn').onchange=renderPhase;renderPhase();
    }
    if(id==='combate'){
      const calc=()=>{const attack=+$('#attack-base').value+1000*+$('#attack-don').value;const defense=+$('#defense-base').value+ +$('#defense-counter').value;$('#attack-output').textContent=attack.toLocaleString('pt-BR');$('#defense-output').textContent=defense.toLocaleString('pt-BR');$('#attack-don-label').textContent=$('#attack-don').value;$('#defense-counter-label').textContent=(+$('#defense-counter').value).toLocaleString('pt-BR');const won=attack>=defense;const needed=Math.max(0,Math.floor((attack-+$('#defense-base').value)/1000)*1000+1000);$('#battle-result').innerHTML=`<b>${won?'O atacante vence esta comparação.':'A defesa impede o dano deste ataque.'}</b><p>${attack===defense?'Os poderes empataram. Empate favorece o atacante. ':''}${won?'Contra um Personagem, o alvo sofreria K.O.; contra um Líder, aplique o procedimento de dano.':'O ataque não causa dano; o atacante não sofre K.O. automaticamente.'} Para superar este ataque, a defesa precisa terminar acima de ${attack.toLocaleString('pt-BR')}. Counter adicional mínimo, em incrementos de 1000: ${Math.max(0,needed-+$('#defense-counter').value).toLocaleString('pt-BR')}.</p>`;};['attack-base','attack-don','defense-base','defense-counter'].forEach(id=>$('#'+id).oninput=calc);calc();
    }
    if(id==='pratica'){
      const renderQuiz=()=>{$('#course-quiz').innerHTML=quiz.map((q,i)=>`<fieldset class="quiz-question"><legend>${String(i+1).padStart(2,'0')}. ${esc(q.q)}</legend>${q.options.map((o,n)=>`<label><input type="radio" name="question-${i}" value="${n}" required><span>${esc(o)}</span></label>`).join('')}<p class="quiz-feedback" id="quiz-feedback-${i}" hidden></p></fieldset>`).join('');$('#quiz-result').hidden=true;};renderQuiz();
      $('#quiz-submit').onclick=()=>{if(!$('#course-quiz').reportValidity())return;let score=0;quiz.forEach((q,i)=>{const chosen=+document.querySelector(`input[name="question-${i}"]:checked`).value;const correct=chosen===q.answer;if(correct)score++;const feedback=$('#quiz-feedback-'+i);feedback.hidden=false;feedback.textContent=(correct?'✓ Correto. ':'↗ Vamos revisar. ')+q.why;});$('#quiz-result').hidden=false;$('#quiz-result').className='quiz-score';$('#quiz-result').innerHTML=`<h3>${score} de ${quiz.length} respostas corretas.</h3><p>${score===quiz.length?'Você acertou todos os conceitos deste exercício. Experimente uma partida e consulte o guia quando surgir uma nova interação.':'Leia as explicações abaixo de cada pergunta e retorne aos capítulos que desejar revisar.'}</p>`;$('#quiz-result').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'center'});};$('#quiz-reset').onclick=()=>{renderQuiz();$('#course-quiz').scrollIntoView({block:'start'});};
    }
  }
  render(Boolean(location.hash));
})();
